async function init(){if(migrateLegacyHash())return;state.view=R.viewFromPath(location.pathname);renderChrome();try{state.authConfig=await api('/auth/config');if(!['tokens','entra','demo','local','hybrid','saml'].includes(state.authConfig.mode))throw new Error('Controller returned an invalid authentication configuration.');if(state.authConfig.mode!=='tokens'){state.token='';sessionStorage.removeItem('segment-token');}applyDashboardIdentity(await api('/auth'));if(state.passwordChangeRequired)showLocalPasswordChange(true);else await load();if(state.view==='activity'&&!state.passwordChangeRequired)await loadActivity();}catch(error){state.authError=error.message;showLogin();}setInterval(()=>{if(!document.hidden&&state.authType)load({quiet:true});},15000);}
init();

